216	/** Reads the settings form from the body; refuses a clerk limit or floor that is negative or has more than two
217	 *  decimals, and terms that are not a whole number of days, and a late percent that is negative or has more than two decimals, and a policy date or period numbering from that is not a calendar date
218	 *  (YYYY-MM-DD). A blank clerk limit means no limit; a blank floor is
219	 *  1.00; blank terms are 14; a blank late percent is 0.00; a blank policy date is the sheet's today; a blank period numbering from is off; a blank entry date is off; a blank cap is none (else an amount like the floor); a blank proof threshold is none (else an amount like the floor); a blank note threshold is none (else an amount like the floor). A grade's terms must be a whole number of days, or blank (the grade uses the sheet's terms). A permission matrix entry must be a comma separated list of
220	 *  roles (clerk, steward), or blank (the standing rule). The grace days must be a whole number of days, or blank (off). A grade's grace days must be a whole number of days, or blank (none). A grade's proof threshold is an amount like the floor, or blank (none: the sheet's applies). The pot is an amount like the floor, or blank (none); not dated. A key left out is not changed.
221	 *  A from-date must be a calendar date (YYYY-MM-DD), or blank (the sheet's today). */
222	public class ValidateSettings {
223	
224	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
225	
226	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
227	
228	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingsException {
229	        List<SettingsInput.Change> changes = new ArrayList<>();
230	        if (request != null) {
231	            amount(changes, Sheet.CLERK_LIMIT, request.clerkLimit(), null, request.clerkLimitFrom(),
232	                    "The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank.");
233	            amount(changes, Sheet.FLOOR, request.floor(), Sheet.DEFAULT_FLOOR, request.floorFrom(),
234	                    "The floor must be an amount, 0.00 or more, with up to two decimals, or blank.");
235	            days(changes, Sheet.TERMS, request.terms(), Sheet.DEFAULT_TERMS, request.termsFrom(),
236	                    "The terms must be a whole number of days, 0 or more, or blank.");
237	            amount(changes, Sheet.LATE_PCT, request.latePct(), Sheet.DEFAULT_LATE_PCT, request.latePctFrom(),
238	                    "The late percent must be a percent, 0.00 or more, with up to two decimals, or blank.");
239	            date(changes, "policy-date", request.policyDate(), "The policy date must be a date (YYYY-MM-DD), or blank.");
240	            date(changes, "period-numbering-from", request.periodNumberingFrom(),
241	                    "The period numbering from must be a date (YYYY-MM-DD), or blank.");
242	            date(changes, Sheet.ENTRY_DATE, request.entryDate(), "The entry date must be a date (YYYY-MM-DD), or blank.");
243	            days(changes, Sheet.TERMS + "-A", request.termsA(), null, request.termsAFrom(),
244	                    "The terms of grade A must be a whole number of days, 0 or more, or blank.");
245	            days(changes, Sheet.TERMS + "-B", request.termsB(), null, request.termsBFrom(),
246	                    "The terms of grade B must be a whole number of days, 0 or more, or blank.");
247	            days(changes, Sheet.TERMS + "-C", request.termsC(), null, request.termsCFrom(),
248	                    "The terms of grade C must be a whole number of days, 0 or more, or blank.");
249	            amount(changes, Sheet.CAP, request.cap(), null, request.capFrom(),
250	                    "The cap must be an amount, 0.00 or more, with up to two decimals, or blank.");
251	            amount(changes, Sheet.PROOF_THRESHOLD, request.proofThreshold(), null, request.proofThresholdFrom(),
252	                    "The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
253	            roles(changes, "open", request.permOpen());
254	            roles(changes, "settle", request.permSettle());
255	            roles(changes, "void", request.permVoid());
256	            roles(changes, "reassign", request.permReassign());
257	            roles(changes, "close", request.permClose());
258	            roles(changes, "reopen", request.permReopen());
259	            graceDays(changes, request.graceDays());
260	            amount(changes, Sheet.NOTE_THRESHOLD, request.noteThreshold(), null, request.noteThresholdFrom(),
261	                    "The note threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
262	            days(changes, Sheet.graceKey("A"), request.graceA(), null, request.graceAFrom(),
263	                    "The grace days of grade A must be a whole number of days, 0 or more, or blank.");
264	            days(changes, Sheet.graceKey("B"), request.graceB(), null, request.graceBFrom(),
265	                    "The grace days of grade B must be a whole number of days, 0 or more, or blank.");
266	            days(changes, Sheet.graceKey("C"), request.graceC(), null, request.graceCFrom(),
267	                    "The grace days of grade C must be a whole number of days, 0 or more, or blank.");
268	            amount(changes, Sheet.proofThresholdKey("A"), request.proofThresholdA(), null, request.proofThresholdAFrom(),
269	                    "The proof threshold of grade A must be an amount, 0.00 or more, with up to two decimals, or blank.");
270	            amount(changes, Sheet.proofThresholdKey("B"), request.proofThresholdB(), null, request.proofThresholdBFrom(),
271	                    "The proof threshold of grade B must be an amount, 0.00 or more, with up to two decimals, or blank.");
272	            amount(changes, Sheet.proofThresholdKey("C"), request.proofThresholdC(), null, request.proofThresholdCFrom(),
273	                    "The proof threshold of grade C must be an amount, 0.00 or more, with up to two decimals, or blank.");
274	            pot(changes, request.pot());
275	        }
276	        body.set(new SettingsInput(changes));
277	    }
278	
279	    /** Adds an amount setting when the form sets it: blank is the given default (null: none). */
280	    private static void amount(List<SettingsInput.Change> changes, String key, String value, BigDecimal blank,
281	            String from, String message) throws InvalidSettingsException {
282	        if (value == null) {
283	            return;
284	        }
285	        BigDecimal amount = blank;
286	        if (!value.trim().isEmpty()) {
287	            if (!AMOUNT.matcher(value.trim()).matches()) {
288	                throw new InvalidSettingsException(message);
289	            }
290	            amount = new BigDecimal(value.trim());
291	        }
292	        changes.add(new SettingsInput.Change(key, amount == null ? null : amount.setScale(2).toPlainString(), true,
293	                from(key, from)));
294	    }
295	
296	    /** Adds a whole-days setting when the form sets it: blank is the given default (null: none). */
297	    private static void days(List<SettingsInput.Change> changes, String key, String value, Integer blank,
298	            String from, String message) throws InvalidSettingsException {
299	        if (value == null) {
300	            return;
301	        }
302	        Integer days = blank;
303	        if (!value.trim().isEmpty()) {
304	            if (!DAYS.matcher(value.trim()).matches()) {
305	                throw new InvalidSettingsException(message);
306	            }
307	            days = Integer.parseInt(value.trim());
308	        }
309	        changes.add(new SettingsInput.Change(key, days == null ? null : String.valueOf(days), true, from(key, from)));
310	    }
311	
312	    /** Adds an undated date setting when the form sets it: blank is null. */
313	    private static void date(List<SettingsInput.Change> changes, String key, String value, String message)
314	            throws InvalidSettingsException {
315	        if (value == null) {
316	            return;
317	        }
318	        LocalDate date = null;
319	        if (!value.trim().isEmpty()) {
320	            try {
321	                date = LocalDate.parse(value.trim());
322	            } catch (DateTimeParseException e) {
323	                throw new InvalidSettingsException(message);
324	            }
325	        }
326	        changes.add(new SettingsInput.Change(key, date == null ? null : date.toString(), false, null));
327	    }
328	
329	    /** Adds an action's permission matrix entry when the form sets it: comma separated roles, each clerk or steward
330	     *  (blank: null, the standing rule). Undated. */
331	    private static void roles(List<SettingsInput.Change> changes, String action, String value)
332	            throws InvalidSettingsException {
333	        if (value == null) {
334	            return;
335	        }
336	        String roles = null;
337	        if (!value.trim().isEmpty()) {
338	            List<String> each = new ArrayList<>();
339	            for (String role : value.split(",", -1)) {
340	                if (!Role.CLERK.equals(role.trim()) && !Role.STEWARD.equals(role.trim())) {
341	                    throw new InvalidSettingsException("The roles that may " + action
342	                            + " must be a comma separated list of clerk and steward, or blank.");
343	                }
344	                if (!each.contains(role.trim())) {
345	                    each.add(role.trim());
346	                }
347	            }
348	            roles = String.join(",", each);
349	        }
350	        changes.add(new SettingsInput.Change(Sheet.permKey(action), roles, false, null));
351	    }
352	
353	    /** Adds the grace days when the form sets them: a whole number of days, or blank (off). Undated. */
354	    private static void graceDays(List<SettingsInput.Change> changes, String value) throws InvalidSettingsException {
355	        if (value == null) {
356	            return;
357	        }
358	        String days = null;
359	        if (!value.trim().isEmpty()) {
360	            if (!DAYS.matcher(value.trim()).matches()) {
361	                throw new InvalidSettingsException("The grace days must be a whole number of days, 0 or more, or blank.");
362	            }
363	            days = String.valueOf(Integer.parseInt(value.trim()));
364	        }
365	        changes.add(new SettingsInput.Change(Sheet.GRACE_DAYS, days, false, null));
366	    }
367	
368	    /** Adds the pot when the form sets it: an amount with up to two decimals, or blank (none). Undated. */
369	    private static void pot(List<SettingsInput.Change> changes, String value) throws InvalidSettingsException {
370	        if (value == null) {
371	            return;
372	        }
373	        String pot = null;
374	        if (!value.trim().isEmpty()) {
375	            if (!AMOUNT.matcher(value.trim()).matches()) {
376	                throw new InvalidSettingsException("The pot must be an amount, 0.00 or more, with up to two decimals, or blank.");
377	            }
378	            pot = new BigDecimal(value.trim()).setScale(2).toPlainString();
379	        }
380	        changes.add(new SettingsInput.Change(Sheet.POT, pot, false, null));
381	    }
382	
383	    /** A setting's from-date: null when blank or left out (the sheet's today). */
384	    private static LocalDate from(String key, String from) throws InvalidSettingsException {
385	        if (from == null || from.trim().isEmpty()) {
386	            return null;
387	        }
388	        try {
389	            return LocalDate.parse(from.trim());
390	        } catch (DateTimeParseException e) {
391	            throw new InvalidSettingsException("The from-date of the " + key + " must be a date (YYYY-MM-DD), or blank.");
392	        }
393	    }
394	}
