523	
524	public interface SettingLogRepository extends JpaRepository<SettingLog, Long> {
525	
526	    /** The sheet's settings set, in the order set. */
527	    List<SettingLog> findBySheetIdOrderByIdAsc(String sheetId);
528	
529	    /** The sheet as it stood at the end of a date, that date standing in for its today: every setting set while
530	     *  its today was on or before it. Only worked out, never saved. */
531	    default Sheet sheetAsOf(Sheet sheet, LocalDate date) {
532	        Sheet then = new Sheet(sheet.getId());
533	        then.setToday(date);
534	        then.setArchived(sheet.archivedBy(date));
535	        for (SettingLog set : findBySheetIdOrderByIdAsc(sheet.getId())) {
536	            if (set.getMadeOn().isAfter(date)) {
537	                continue;
538	            }
539	            if (Sheet.POLICY_DATE.equals(set.getKey())) {
540	                then.setPolicyDate(set.getValue() == null ? null : LocalDate.parse(set.getValue()));
541	            } else if (Sheet.PERIOD_NUMBERING_FROM.equals(set.getKey())) {
542	                then.setPeriodNumberingFrom(set.getValue() == null ? null : LocalDate.parse(set.getValue()));
543	            } else if (Sheet.ENTRY_DATE.equals(set.getKey())) {
544	                then.setEntryDate(set.getValue() == null ? null : LocalDate.parse(set.getValue()));
545	            } else {
546	                then.record(set.getKey(), set.getFromDate(), set.getValue());
547	            }
548	        }
549	        return then;
550	    }
551	}
