674	    /** Records a setting's value from a date on (null: blank), replacing the value already recorded from that date. */
675	    public void record(String key, LocalDate from, String value) {
676	        for (SheetSetting s : settings) {
677	            if (s.getKey().equals(key) && Objects.equals(s.getFromDate(), from)) {
678	                s.setValue(value);
679	                return;
680	            }
681	        }
682	        settings.add(new SheetSetting(this, key, from, value));
683	    }
