685	    /** The setting recorded for a key in force on a date: the one with the latest from-date on or before it; none
686	     *  before every from-date. */
687	    private Optional<SheetSetting> settingOn(String key, LocalDate on) {
688	        return settings.stream()
689	                .filter(s -> s.getKey().equals(key))
690	                .filter(s -> s.getFromDate() == null || !s.getFromDate().isAfter(on))
691	                .max(Comparator.comparing(SheetSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
692	    }
693	
694	    /** The value of a setting in force on a date, as recorded (null: blank, or none recorded). */
695	    public String valueOn(String key, LocalDate on) {
696	        return settingOn(key, on).map(SheetSetting::getValue).orElse(null);
697	    }
