727	    /** The grade's own terms in days in force on a date (grades A, B and C); null when it has none and uses the
728	     *  sheet's terms. */
729	    public Integer gradeTermsOn(String grade, LocalDate on) {
730	        String terms = valueOn(TERMS + "-" + grade, on);
731	        return terms != null ? Integer.valueOf(terms) : null;
732	    }
733	
734	    /** The terms for a person on a date: their own terms when they have any, else their grade's in force then. */
735	    public int termsFor(Integer own, String grade, LocalDate on) {
736	        return own != null ? own : termsFor(grade, on);
737	    }
738	
739	    /** The setting key of a grade's grace days (dated). */
740	    public static String graceKey(String grade) {
741	        return "grace-" + grade;
742	    }
743	
744	    /** The grade's grace days in force on a date (grades A, B and C): an overdue claim's lateness counts from its
745	     *  due-by plus them; null when it has none. */
746	    public Integer gradeGraceOn(String grade, LocalDate on) {
747	        String days = grade == null ? null : valueOn(graceKey(grade), on);
748	        return days != null ? Integer.valueOf(days) : null;
749	    }
750	
