package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SettingLog;
import net.officefloor.hq.app.sheet.SettingLogRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Sets the settings the form sets: a setting that carries a figure (the clerk limit, floor, terms, late percent,
 *  each grade's own terms, cap, proof threshold, note threshold, each grade's grace days, each grade's proof threshold) is recorded from its from-date (the sheet's today when none is given), replacing a
 *  value recorded from that date and keeping the others; the policy date, period numbering from and entry date are set; a permission matrix entry
 *  (key perm-<action>), the grace days and the pot are recorded undated. Each is logged with the sheet's today (so the
 *  settings can be worked out as they stood on an earlier date). */
public class ApplySettings {
    public void apply(@Val SettingsInput input, @Val Sheet sheet, SheetRepository repository, SettingLogRepository log) {
        for (SettingsInput.Change change : input.changes()) {
            LocalDate from = null;
            if (change.dated()) {
                from = change.from() != null ? change.from() : sheet.getToday();
                sheet.record(change.key(), from, change.value());
            } else if (change.key().startsWith("perm-") || Sheet.GRACE_DAYS.equals(change.key())
                    || Sheet.POT.equals(change.key())) {
                sheet.record(change.key(), null, change.value());
            } else if (Sheet.POLICY_DATE.equals(change.key())) {
                sheet.setPolicyDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if (Sheet.PERIOD_NUMBERING_FROM.equals(change.key())) {
                sheet.setPeriodNumberingFrom(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if (Sheet.ENTRY_DATE.equals(change.key())) {
                sheet.setEntryDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else {
                continue;
            }
            log.save(new SettingLog(sheet.getId(), change.key(), from, change.value(), sheet.getToday()));
        }
        repository.saveAndFlush(sheet);
        log.flush();
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records each setting the form set, once it is saved, with the value saved: the clerk limit (blank when there is none), then the floor, then the terms, then the late percent, then the policy date (blank when it is the sheet's today), then the period numbering from (blank when off), then each grade's own terms (key terms-<grade>; blank when it uses the sheet's terms), then the cap (blank when there is none), then the proof threshold (blank when there is none), then the permission matrix entries, then the grace days, then the note threshold (blank when there is none), then the entry date (blank when off), then each grade's grace days (key grace-<grade>; blank when none), then each grade's proof threshold (key proof-threshold-<grade>; blank when none), then the pot (blank when there is none); a dated setting ends with from=<date> when a from-date was given. */
public class AuditSettingChanged {
    public void audit(@Val SettingsInput input, @Val Sheet sheet,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String head = "SETTING_CHANGED sheet=" + sheet.getId() + " by=" + AuditUser.decode(user);
        for (SettingsInput.Change change : input.changes()) {
            audit.record(head + " key=" + change.key() + " value=" + (change.value() == null ? "" : change.value())
                    + (change.from() == null ? "" : " from=" + change.from()));
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidSettings {
    public void handle(@Parameter InvalidSettingsException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.setting;

/** A settings form that cannot be saved: a clerk limit or floor that is not blank nor an amount with up to two decimals. */
public class InvalidSettingsException extends Exception {
    public InvalidSettingsException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.history.AsOf;
import net.officefloor.hq.app.sheet.InvalidTodayException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's settings; as of a date (asOf), as they stood at the end of it. */
public class RespondWithSettings {
    public void respond(@Val Sheet sheet, @RequestParam(name = "asOf", required = false) String asOfParam, AsOf asOf,
            ObjectResponse<SettingsResponse> response) throws InvalidTodayException {
        response.send(SettingsResponse.from(asOf.sheet(sheet, AsOf.dateOf(asOfParam))));
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.List;

/** A validated settings form: the settings it sets, in the order they are recorded — the clerk limit, the floor, the
 *  terms, the late percent, the policy date, the period numbering from, the terms of grades A, B and C, the cap, the proof threshold, the
 *  permission matrix entries for open, settle, void, reassign, close and reopen, the grace days, the note threshold, the entry date, each grade's grace days and proof threshold, the pot. */
public record SettingsInput(List<Change> changes) {

    /** A setting the form sets: its key (as the audit names it), its value as the screen shows it (null: blank —
     *  no clerk limit, no cap, a grade on the sheet's terms, the policy date on the sheet's today, the period
     *  numbering off), and whether it is dated, and the from-date given (null: none given — a dated setting is then
     *  recorded from the sheet's today). */
    public record Change(String key, String value, boolean dated, LocalDate from) {
    }

    public boolean sets(String key) {
        return changes.stream().anyMatch(c -> c.key().equals(key));
    }
}
package net.officefloor.hq.app.setting;

/** The settings form as submitted: the clerk limit (blank: no limit), the floor (blank: 1.00) and the terms in
 *  days (blank: 14) and the late percent
 *  (blank: 0.00) and the policy date (YYYY-MM-DD; blank: the sheet's today) and the period numbering from (YYYY-MM-DD; blank: off) and the terms of grades A, B and C in days (blank: the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none); and the permission matrix entries for open, settle, void, reassign, close and reopen
 *  (comma separated roles; blank: the standing rule); and the grace days (a whole number of days; blank: off; not dated); and the note threshold (blank: none); and the entry date (YYYY-MM-DD; blank: off; not dated); and the grace days of grades A, B and C (blank: none); and the proof thresholds of grades A, B and C (blank: none — the sheet's applies); and the pot (two decimals; blank: none; not dated); a key left out (null) is not changed.
 *  Each setting that carries a figure has its from-date (YYYY-MM-DD; blank or left out: the sheet's today): it is
 *  recorded from that date on. */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String termsA, String termsB, String termsC, String cap, String proofThreshold,
        String clerkLimitFrom, String floorFrom, String termsFrom, String latePctFrom,
        String termsAFrom, String termsBFrom, String termsCFrom, String capFrom, String proofThresholdFrom,
        String permOpen, String permSettle, String permVoid, String permReassign, String permClose, String permReopen,
        String graceDays, String noteThreshold, String noteThresholdFrom, String entryDate,
        String graceA, String graceB, String graceC, String graceAFrom, String graceBFrom, String graceCFrom,
        String proofThresholdA, String proofThresholdB, String proofThresholdC,
        String proofThresholdAFrom, String proofThresholdBFrom, String proofThresholdCFrom, String pot) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetSetting;

/** The sheet's settings as the screen shows them, each in force on the sheet's today: the clerk limit with two decimals (null: no limit) and the
 *  floor with two decimals, and the terms in days, and the late percent with two decimals, and the policy date (YYYY-MM-DD; "" when
 *  blank: the sheet's today), and the period numbering from (YYYY-MM-DD; "" when off), and the own terms in days of grades A, B and C
 *  ("" when the grade uses the sheet's terms), and the cap with two decimals ("" when there is none), and the proof threshold with two decimals ("" when there is none); and the values recorded
 *  for each dated setting, by key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap), by from-date; and the permission matrix
 *  entry of each of open, settle, void, reassign, close and reopen (its comma separated roles; "" when blank: the standing rule); and the grace days ("" when off); and the note threshold with two decimals ("" when there is none); and the entry date (YYYY-MM-DD; "" when off); and the grace days of grades A, B and C in force ("" when none); and the proof thresholds of grades A, B and C in force ("" when none); and the pot with two decimals ("" when there is none; not dated). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap, String proofThreshold,
        Map<String, List<Dated>> dated, String permOpen, String permSettle, String permVoid, String permReassign,
        String permClose, String permReopen, String graceDays, String noteThreshold, String entryDate,
        String graceA, String graceB, String graceC,
        String proofThresholdA, String proofThresholdB, String proofThresholdC, String pot) {

    /** A value recorded from a date on (null from: the beginning of time; null value: blank). */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Sheet sheet) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (SheetSetting s : sheet.getSettings()) {
            dated.computeIfAbsent(s.getKey(), k -> new ArrayList<>())
                    .add(new Dated(s.getFromDate() == null ? null : s.getFromDate().toString(), s.getValue()));
        }
        return new SettingsResponse(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                sheet.floorOn(sheet.getToday()).setScale(2).toPlainString(), String.valueOf(sheet.termsOn(sheet.getToday())),
                sheet.latePctOn(sheet.getToday()).setScale(2).toPlainString(),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                gradeTerms(sheet, "A"), gradeTerms(sheet, "B"), gradeTerms(sheet, "C"),
                sheet.getCap() == null ? "" : sheet.getCap().toPlainString(),
                sheet.proofThresholdOn(sheet.getToday()) == null ? "" : sheet.proofThresholdOn(sheet.getToday()).toPlainString(),
                dated, sheet.permOf("open"), sheet.permOf("settle"), sheet.permOf("void"), sheet.permOf("reassign"),
                sheet.permOf("close"), sheet.permOf("reopen"),
                sheet.getGraceDays() == null ? "" : String.valueOf(sheet.getGraceDays()),
                sheet.noteThresholdOn(sheet.getToday()) == null ? "" : sheet.noteThresholdOn(sheet.getToday()).toPlainString(),
                sheet.getEntryDate() == null ? "" : sheet.getEntryDate().toString(),
                gradeGrace(sheet, "A"), gradeGrace(sheet, "B"), gradeGrace(sheet, "C"),
                gradeProofThreshold(sheet, "A"), gradeProofThreshold(sheet, "B"), gradeProofThreshold(sheet, "C"),
                sheet.getPot() == null ? "" : sheet.getPot().toPlainString());
    }

    /** The grade's grace days in force on the sheet's today; "" when it has none. */
    public static String gradeGrace(Sheet sheet, String grade) {
        Integer grace = sheet.gradeGraceOn(grade, sheet.getToday());
        return grace == null ? "" : String.valueOf(grace);
    }

    /** The grade's proof threshold in force on the sheet's today with two decimals; "" when it has none. */
    public static String gradeProofThreshold(Sheet sheet, String grade) {
        BigDecimal threshold = sheet.gradeProofThresholdOn(grade, sheet.getToday());
        return threshold == null ? "" : threshold.toPlainString();
    }

    /** The grade's own terms in days in force on the sheet's today; "" when it uses the sheet's terms. */
    public static String gradeTerms(Sheet sheet, String grade) {
        Integer terms = sheet.gradeTermsOn(grade, sheet.getToday());
        return terms == null ? "" : String.valueOf(terms);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the settings form from the body; refuses a clerk limit or floor that is negative or has more than two
 *  decimals, and terms that are not a whole number of days, and a late percent that is negative or has more than two decimals, and a policy date or period numbering from that is not a calendar date
 *  (YYYY-MM-DD). A blank clerk limit means no limit; a blank floor is
 *  1.00; blank terms are 14; a blank late percent is 0.00; a blank policy date is the sheet's today; a blank period numbering from is off; a blank entry date is off; a blank cap is none (else an amount like the floor); a blank proof threshold is none (else an amount like the floor); a blank note threshold is none (else an amount like the floor). A grade's terms must be a whole number of days, or blank (the grade uses the sheet's terms). A permission matrix entry must be a comma separated list of
 *  roles (clerk, steward), or blank (the standing rule). The grace days must be a whole number of days, or blank (off). A grade's grace days must be a whole number of days, or blank (none). A grade's proof threshold is an amount like the floor, or blank (none: the sheet's applies). The pot is an amount like the floor, or blank (none); not dated. A key left out is not changed.
 *  A from-date must be a calendar date (YYYY-MM-DD), or blank (the sheet's today). */
public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingsException {
        List<SettingsInput.Change> changes = new ArrayList<>();
        if (request != null) {
            amount(changes, Sheet.CLERK_LIMIT, request.clerkLimit(), null, request.clerkLimitFrom(),
                    "The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.FLOOR, request.floor(), Sheet.DEFAULT_FLOOR, request.floorFrom(),
                    "The floor must be an amount, 0.00 or more, with up to two decimals, or blank.");
            days(changes, Sheet.TERMS, request.terms(), Sheet.DEFAULT_TERMS, request.termsFrom(),
                    "The terms must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.LATE_PCT, request.latePct(), Sheet.DEFAULT_LATE_PCT, request.latePctFrom(),
                    "The late percent must be a percent, 0.00 or more, with up to two decimals, or blank.");
            date(changes, "policy-date", request.policyDate(), "The policy date must be a date (YYYY-MM-DD), or blank.");
            date(changes, "period-numbering-from", request.periodNumberingFrom(),
                    "The period numbering from must be a date (YYYY-MM-DD), or blank.");
            date(changes, Sheet.ENTRY_DATE, request.entryDate(), "The entry date must be a date (YYYY-MM-DD), or blank.");
            days(changes, Sheet.TERMS + "-A", request.termsA(), null, request.termsAFrom(),
                    "The terms of grade A must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.TERMS + "-B", request.termsB(), null, request.termsBFrom(),
                    "The terms of grade B must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.TERMS + "-C", request.termsC(), null, request.termsCFrom(),
                    "The terms of grade C must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.CAP, request.cap(), null, request.capFrom(),
                    "The cap must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.PROOF_THRESHOLD, request.proofThreshold(), null, request.proofThresholdFrom(),
                    "The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
            roles(changes, "open", request.permOpen());
            roles(changes, "settle", request.permSettle());
            roles(changes, "void", request.permVoid());
            roles(changes, "reassign", request.permReassign());
            roles(changes, "close", request.permClose());
            roles(changes, "reopen", request.permReopen());
            graceDays(changes, request.graceDays());
            amount(changes, Sheet.NOTE_THRESHOLD, request.noteThreshold(), null, request.noteThresholdFrom(),
                    "The note threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
            days(changes, Sheet.graceKey("A"), request.graceA(), null, request.graceAFrom(),
                    "The grace days of grade A must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.graceKey("B"), request.graceB(), null, request.graceBFrom(),
                    "The grace days of grade B must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.graceKey("C"), request.graceC(), null, request.graceCFrom(),
                    "The grace days of grade C must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.proofThresholdKey("A"), request.proofThresholdA(), null, request.proofThresholdAFrom(),
                    "The proof threshold of grade A must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.proofThresholdKey("B"), request.proofThresholdB(), null, request.proofThresholdBFrom(),
                    "The proof threshold of grade B must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.proofThresholdKey("C"), request.proofThresholdC(), null, request.proofThresholdCFrom(),
                    "The proof threshold of grade C must be an amount, 0.00 or more, with up to two decimals, or blank.");
            pot(changes, request.pot());
        }
        body.set(new SettingsInput(changes));
    }

    /** Adds an amount setting when the form sets it: blank is the given default (null: none). */
    private static void amount(List<SettingsInput.Change> changes, String key, String value, BigDecimal blank,
            String from, String message) throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        BigDecimal amount = blank;
        if (!value.trim().isEmpty()) {
            if (!AMOUNT.matcher(value.trim()).matches()) {
                throw new InvalidSettingsException(message);
            }
            amount = new BigDecimal(value.trim());
        }
        changes.add(new SettingsInput.Change(key, amount == null ? null : amount.setScale(2).toPlainString(), true,
                from(key, from)));
    }

    /** Adds a whole-days setting when the form sets it: blank is the given default (null: none). */
    private static void days(List<SettingsInput.Change> changes, String key, String value, Integer blank,
            String from, String message) throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        Integer days = blank;
        if (!value.trim().isEmpty()) {
            if (!DAYS.matcher(value.trim()).matches()) {
                throw new InvalidSettingsException(message);
            }
            days = Integer.parseInt(value.trim());
        }
        changes.add(new SettingsInput.Change(key, days == null ? null : String.valueOf(days), true, from(key, from)));
    }

    /** Adds an undated date setting when the form sets it: blank is null. */
    private static void date(List<SettingsInput.Change> changes, String key, String value, String message)
            throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        LocalDate date = null;
        if (!value.trim().isEmpty()) {
            try {
                date = LocalDate.parse(value.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingsException(message);
            }
        }
        changes.add(new SettingsInput.Change(key, date == null ? null : date.toString(), false, null));
    }

    /** Adds an action's permission matrix entry when the form sets it: comma separated roles, each clerk or steward
     *  (blank: null, the standing rule). Undated. */
    private static void roles(List<SettingsInput.Change> changes, String action, String value)
            throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        String roles = null;
        if (!value.trim().isEmpty()) {
            List<String> each = new ArrayList<>();
            for (String role : value.split(",", -1)) {
                if (!Role.CLERK.equals(role.trim()) && !Role.STEWARD.equals(role.trim())) {
                    throw new InvalidSettingsException("The roles that may " + action
                            + " must be a comma separated list of clerk and steward, or blank.");
                }
                if (!each.contains(role.trim())) {
                    each.add(role.trim());
                }
            }
            roles = String.join(",", each);
        }
        changes.add(new SettingsInput.Change(Sheet.permKey(action), roles, false, null));
    }

    /** Adds the grace days when the form sets them: a whole number of days, or blank (off). Undated. */
    private static void graceDays(List<SettingsInput.Change> changes, String value) throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        String days = null;
        if (!value.trim().isEmpty()) {
            if (!DAYS.matcher(value.trim()).matches()) {
                throw new InvalidSettingsException("The grace days must be a whole number of days, 0 or more, or blank.");
            }
            days = String.valueOf(Integer.parseInt(value.trim()));
        }
        changes.add(new SettingsInput.Change(Sheet.GRACE_DAYS, days, false, null));
    }

    /** Adds the pot when the form sets it: an amount with up to two decimals, or blank (none). Undated. */
    private static void pot(List<SettingsInput.Change> changes, String value) throws InvalidSettingsException {
        if (value == null) {
            return;
        }
        String pot = null;
        if (!value.trim().isEmpty()) {
            if (!AMOUNT.matcher(value.trim()).matches()) {
                throw new InvalidSettingsException("The pot must be an amount, 0.00 or more, with up to two decimals, or blank.");
            }
            pot = new BigDecimal(value.trim()).setScale(2).toPlainString();
        }
        changes.add(new SettingsInput.Change(Sheet.POT, pot, false, null));
    }

    /** A setting's from-date: null when blank or left out (the sheet's today). */
    private static LocalDate from(String key, String from) throws InvalidSettingsException {
        if (from == null || from.trim().isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(from.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSettingsException("The from-date of the " + key + " must be a date (YYYY-MM-DD), or blank.");
        }
    }
}
