python3 - <<'EOF'
import re
p='rate/RateRepository.java'
s=open(p).read()
s=s.replace("import java.time.LocalDate;\n","import java.time.LocalDate;\nimport java.util.ArrayList;\n")
s=s.replace("import org.springframework.data.jpa.repository.JpaRepository;\n","import org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.Query;\nimport org.springframework.data.repository.query.Param;\n")
s=s.rstrip()[:-1]+'''
    /** How many sheets up a sheet's rates are looked for: its parent, its parent's parent, and one more. */
    int CHAIN_LEVELS = 3;

    /** The parent sheet a sheet names (its undated parent setting); empty (or a null value) when none. */
    @Query("select s.value from SheetSetting s where s.sheet.id = :sheetId and s.key = 'parent'")
    List<String> parentsOf(@Param("sheetId") String sheetId);

    /** The sheet's id, then its parent's, then its parent's parent, up to three levels up. */
    default List<String> chainOf(String sheetId) {
        List<String> chain = new ArrayList<>(List.of(sheetId));
        String id = sheetId;
        for (int level = 0; level < CHAIN_LEVELS; level++) {
            String parent = parentsOf(id).stream().filter(p -> p != null).findFirst().orElse(null);
            if (parent == null || chain.contains(parent)) {
                break;
            }
            chain.add(parent);
            id = parent;
        }
        return chain;
    }

    /** The sheet's rates (as {@link #findBySheetIdOrderByGradeAscFromDateAscIdAsc}), then those of each sheet up its
     *  chain ({@link #chainOf}) in turn: a grade with no rate in force on a date on a sheet takes the next one's. */
    default List<Rate> findInChain(String sheetId) {
        List<Rate> rates = new ArrayList<>();
        for (String id : chainOf(sheetId)) {
            rates.addAll(findBySheetIdOrderByGradeAscFromDateAscIdAsc(id));
        }
        return rates;
    }
}
'''
open(p,'w').write(s)

p='claim/ClaimFigures.java'
s=open(p).read()
old=s[s.index("    /** The percent of the grade's rate in force on a date; none"):s.index("    /** The due the claim would have today")]
new='''    /** The percent of the grade's rate in force on a date; none when that rate's to-date is before it. When the
     *  sheet has none in force then, the next sheet up its chain's (the rates of each sheet come in chain order). */
    private Optional<BigDecimal> rateOn(String grade, LocalDate on) {
        List<String> chain = new ArrayList<>(List.of(sheet.getId()));
        rates.stream().map(Rate::getSheetId).filter(id -> !chain.contains(id)).forEach(chain::add);
        for (String sheetId : chain) {
            Optional<BigDecimal> pct = rates.stream()
                    .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
                    .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
                    .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                    .filter(r -> !r.endedBy(on))
                    .map(Rate::getPct);
            if (pct.isPresent()) {
                return pct;
            }
        }
        return Optional.empty();
    }

'''
s=s.replace(old,new).replace("import java.util.Comparator;","import java.util.ArrayList;\nimport java.util.Comparator;")
open(p,'w').write(s)
